from pysat.solvers import Glucose3
from pysat.card import *
import itertools

n = 13
vertices = list(range(n))
edges = [(u, v) for u in range(n) for v in range(u+1, n)]
m = len(edges)  # 78 possible edges

edge_to_var = {e: i+1 for i, e in enumerate(edges)}

solver = Glucose3()

# Constraint 1: At least 22 edges
clauses = CardEnc.atleast(lits=list(range(1, m+1)), bound=22, encoding=EncType.pairwise)
for clause in clauses:
    solver.add_clause(clause)

# Constraint 2: No cycles of length 3, 4, 5, or 6

# Cycles of length 3 (triangles)
for a, b, c in itertools.combinations(vertices, 3):
    e1 = edge_to_var[tuple(sorted((a, b)))]
    e2 = edge_to_var[tuple(sorted((b, c)))]
    e3 = edge_to_var[tuple(sorted((a, c)))]
    solver.add_clause([-e1, -e2, -e3])

# Cycles of length 4
for a, b, c, d in itertools.combinations(vertices, 4):
    cycle_edges = [
        [(a,b), (b,c), (c,d), (d,a)],
        [(a,b), (b,d), (d,c), (c,a)],
        [(a,c), (c,b), (b,d), (d,a)]
    ]
    for cycle in cycle_edges:
        vars_in_cycle = [edge_to_var[tuple(sorted(e))] for e in cycle]
        solver.add_clause([-v for v in vars_in_cycle])

print("Added triangle and 4-cycle constraints")

# Cycles of length 5
count = 0
for cycle in itertools.permutations(vertices, 5):
    if cycle[0] != min(cycle):
        continue
    if len(set(cycle)) < 5:
        continue
    cycle_edges = []
    for i in range(5):
        u, v = cycle[i], cycle[(i+1)%5]
        if u > v:
            u, v = v, u
        cycle_edges.append(edge_to_var[(u, v)])
    solver.add_clause([-v for v in cycle_edges])
    count += 1

print(f"Added {count} 5-cycle constraints")

# Cycles of length 6
count = 0
for cycle in itertools.permutations(vertices, 6):
    if cycle[0] != min(cycle):
        continue
    if len(set(cycle)) < 6:
        continue
    cycle_edges = []
    for i in range(6):
        u, v = cycle[i], cycle[(i+1)%6]
        if u > v:
            u, v = v, u
        cycle_edges.append(edge_to_var[(u, v)])
    solver.add_clause([-v for v in cycle_edges])
    count += 1

print(f"Added {count} 6-cycle constraints")

# Constraint 3: 4-colorable
color_vars = {}
for v in vertices:
    for c in range(4):
        color_vars[(v, c)] = m + 1 + v * 4 + c

for v in vertices:
    vars_for_v = [color_vars[(v, c)] for c in range(4)]
    solver.add_clause(vars_for_v)
    for c1 in range(4):
        for c2 in range(c1+1, 4):
            solver.add_clause([-color_vars[(v, c1)], -color_vars[(v, c2)]])

for u, v in edges:
    for c in range(4):
        solver.add_clause([-edge_to_var[(u, v)], -color_vars[(u, c)], -color_vars[(v, c)]])

print("Added coloring constraints")
print(f"Total variables: {m + 13*4}")
print(f"Solving...")

if solver.solve():
    model = solver.get_model()
    print("SAT!")
    selected_edges = []
    for e, var in edge_to_var.items():
        if var in model:
            selected_edges.append(e)
    print(f"Number of edges: {len(selected_edges)}")
    print(f"Edges: {selected_edges}")

    coloring = {}
    for v in vertices:
        for c in range(4):
            var = color_vars[(v, c)]
            if var in model and model.index(var) >= 0:
                coloring[v] = c
    print(f"Coloring: {coloring}")
else:
    print("UNSAT with current constraints")

