    """Check if the graph has a cycle of given length"""
    adj = {v: set() for v in vertices}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # BFS/DFS to find cycles
    def find_cycle_from(start, current, path, visited):
        if len(path) == length:
            if start in adj[current]:
                return True
            return False
        for neighbor in adj[current]:
            if neighbor == start and len(path) == length - 1:
                return True
            if neighbor not in visited and neighbor != path[-2] if len(path) > 1 else True:
                visited.add(neighbor)
