def has_short_cycle(adj, new_u, new_v, max_len=6):
    """Check if adding edge (new_u, new_v) creates a cycle of length <= max_len"""
    # BFS from new_u, avoiding the direct edge to new_v
    # If we reach new_v within max_len-1 steps, we have a short cycle

    from collections import deque

    # BFS from new_u
    visited = {new_u: 0}
    queue = deque([new_u])

    while queue:
        node = queue.popleft()
        dist = visited[node]

        if dist >= max_len - 1:
            continue

        for neighbor in adj[node]:
            if neighbor == new_v and dist + 1 <= max_len - 1:
                return True  # Found cycle of length dist + 2
            if neighbor not in visited and neighbor != new_u:
                visited[neighbor] = dist + 1
                queue.append(neighbor)

    return False

